<?php
/**
 * File for the language switcher module for Divi 4.
 *
 * This file is only loaded via the Divi hook "et_builder_ready" (where ET_Builder_Module exists).
 *
 * @package easy-language
 */

namespace easyLanguage\PageBuilder\Divi;

// prevent direct access.
defined( 'ABSPATH' ) || exit;

use easyLanguage\EasyLanguage\Switcher;
use ET_Builder_Module;

/**
 * Object to handle the language switcher module in Divi 4.
 *
 * The settings are generated from the field definitions of the switcher, the output is generated by the switcher.
 * The module uses the partial support of the Divi visual builder: the preview is rendered via PHP (AJAX).
 *
 * @noinspection PhpUnused
 */
class Switcher_Module extends ET_Builder_Module {
	/**
	 * The slug of this module (shortcode name).
	 *
	 * @var string
	 */
	public $slug = 'easy_language_switcher';

	/**
	 * Support of the visual builder: "partial" = the module output is rendered via PHP in the visual builder.
	 *
	 * @var string
	 */
	public $vb_support = 'partial';

	/**
	 * Path to the icon of this module in the Divi builder (SVG, the Easy Language icon like in the other builders).
	 *
	 * @var string
	 */
	public $icon_path = '';

	/**
	 * Credits of this module, shown in the Divi builder.
	 *
	 * @var array<string,string>
	 */
	protected $module_credits = array(
		'module_uri' => 'https://wordpress.org/plugins/easy-language/',
		'author'     => 'laOlaWeb',
		'author_uri' => 'https://laolaweb.com',
	);

	/**
	 * Initialize the module.
	 *
	 * @return void
	 */
	public function init(): void {
		// use the Easy Language icon.
		$this->icon_path = \easyLanguage\Plugin\Helper::get_plugin_path() . 'gfx/easy-language-icon.svg';

		$this->name   = __( 'Language Switcher', 'easy-language' );
		$this->plural = __( 'Language Switchers', 'easy-language' );

		// define the toggles (= sections) of the settings.
		$this->settings_modal_toggles = array(
			'general'  => array(
				'toggles' => array(),
			),
			'advanced' => array(
				'toggles' => array(),
			),
		);
		$priority                     = 10;
		foreach ( Switcher::get_instance()->get_widget_sections() as $section => $title ) {
			$this->settings_modal_toggles[ $this->get_tab_slug( $section ) ]['toggles'][ $this->get_toggle_slug( $section ) ] = array(
				'title'    => $title,
				'priority' => $priority,
			);
			$priority += 10;
		}

		// configure the design options of Divi: our output has no own texts or buttons to style.
		$this->advanced_fields = array(
			'fonts'        => false,
			'text'         => false,
			'button'       => false,
			'link_options' => false,
		);
	}

	/**
	 * Return the fields of this module, generated from the field definitions of the switcher.
	 *
	 * @return array<string,array<string,mixed>>
	 */
	public function get_fields(): array {
		$fields = array();
		foreach ( Switcher::get_instance()->get_widget_fields() as $name => $field ) {
			// get the basic settings for any field.
			$section  = (string) $field['section'];
			$settings = array(
				'label'           => $field['label'],
				'option_category' => 'design' === $section ? 'layout' : 'configuration',
				'tab_slug'        => $this->get_tab_slug( $section ),
				'toggle_slug'     => $this->get_toggle_slug( $section ),
				'default'         => is_scalar( $field['default'] ) ? (string) $field['default'] : '',
			);
			if ( ! empty( $field['description'] ) ) {
				$settings['description'] = $field['description'];
			}

			// add the settings depending on the field type.
			switch ( $field['type'] ) {
				case 'select':
					$settings['type']    = 'select';
					$settings['options'] = $field['options'];
					break;
				case 'switch':
					$settings['type']    = 'yes_no_button';
					$settings['options'] = array(
						'off' => __( 'No', 'easy-language' ),
						'on'  => __( 'Yes', 'easy-language' ),
					);
					$settings['default'] = $field['default'] ? 'on' : 'off';
					break;
				case 'size':
					$units                      = ! empty( $field['units'] ) ? (array) $field['units'] : array( 'px' );
					$settings['type']           = 'range';
					$settings['allowed_units']  = $units;
					$settings['default_unit']   = (string) reset( $units );
					$settings['validate_unit']  = true;
					$settings['range_settings'] = array(
						'min'  => '0',
						'max'  => '100',
						'step' => '1',
					);
					break;
				case 'color':
					$settings['type']         = 'color-alpha';
					$settings['custom_color'] = true;
					$settings['default']      = '';
					break;
				case 'objects':
					// Divi 4 has no searchable multi select: use a text field with a comma separated list.
					$settings['type']        = 'text';
					$settings['default']     = is_array( $field['default'] ) ? implode( ',', $field['default'] ) : $settings['default'];
					$settings['description'] = trim( ( $field['description'] ?? '' ) . ' ' . __( 'Comma separated list of pages and terms, e.g. post:12,term:5.', 'easy-language' ) );
					break;
				default:
					$settings['type'] = 'text';
			}

			// add the conditions.
			if ( ! empty( $field['condition'] ) && is_array( $field['condition'] ) ) {
				$settings['show_if'] = $this->get_show_if( $field['condition'] );
			}

			// add the field.
			$fields[ $name ] = $settings;
		}

		// return the resulting fields.
		return $fields;
	}

	/**
	 * Render the output of the module in frontend and in the visual builder.
	 *
	 * @param array<string,mixed> $attrs       List of unprocessed attributes.
	 * @param string|null         $content     Content being processed.
	 * @param string              $render_slug Slug of module that is used for rendering output.
	 *
	 * @return string
	 */
	public function render( $attrs, $content, $render_slug ): string { // phpcs:ignore Generic.CodeAnalysis.UnusedFunctionParameter.FoundBeforeLastUsed
		// collect the values of our fields.
		$values = array();
		foreach ( array_keys( Switcher::get_instance()->get_widget_fields() ) as $name ) {
			if ( isset( $this->props[ $name ] ) ) {
				$values[ $name ] = $this->props[ $name ];
			}
		}

		// get the output.
		$output = Switcher::get_instance()->render_widget( $values, 'divi', $this->is_preview() );

		// bail if the switcher is not visible on this page.
		if ( empty( $output ) ) {
			return '';
		}

		// return the output in the wrapper of Divi (for the design options of Divi).
		return $this->_render_module_wrapper( $output, $render_slug );
	}

	/**
	 * Return whether the module is rendered in the Divi builder (visual builder or its preview).
	 *
	 * @return bool
	 */
	private function is_preview(): bool {
		// the visual builder renders modules with partial support via AJAX.
		// phpcs:ignore WordPress.Security.NonceVerification.Missing -- only checking the requested action, the nonce is checked by Divi.
		if ( wp_doing_ajax() && isset( $_POST['action'] ) && 'et_fb_ajax_render_shortcode' === sanitize_key( wp_unslash( $_POST['action'] ) ) ) {
			return true;
		}

		// check the visual builder itself.
		if ( function_exists( 'et_core_is_fb_enabled' ) && et_core_is_fb_enabled() ) {
			return true;
		}

		// check the preview of the backend builder.
		return function_exists( 'is_et_pb_preview' ) && is_et_pb_preview();
	}

	/**
	 * Return the Divi tab slug for a section of the switcher fields.
	 *
	 * @param string $section The section.
	 *
	 * @return string
	 */
	private function get_tab_slug( string $section ): string {
		return 'design' === $section ? 'advanced' : 'general';
	}

	/**
	 * Return the Divi toggle slug for a section of the switcher fields.
	 *
	 * @param string $section The section.
	 *
	 * @return string
	 */
	private function get_toggle_slug( string $section ): string {
		return 'easy_language_' . sanitize_key( $section );
	}

	/**
	 * Convert the condition of a switcher field to the "show_if" setting of Divi.
	 *
	 * @param array<string,mixed> $condition The condition (field name => allowed values).
	 *
	 * @return array<string,mixed>
	 */
	private function get_show_if( array $condition ): array {
		$fields  = Switcher::get_instance()->get_widget_fields();
		$show_if = array();
		foreach ( $condition as $field_name => $allowed_values ) {
			$allowed_values = array_values( (array) $allowed_values );

			// switches use "on" and "off" in Divi.
			if ( isset( $fields[ $field_name ] ) && 'switch' === $fields[ $field_name ]['type'] ) {
				$allowed_values = array_map(
					static function ( $value ): string {
						return $value ? 'on' : 'off';
					},
					$allowed_values
				);
			}

			// add the condition (Divi supports single values and lists of values).
			$show_if[ $field_name ] = 1 === count( $allowed_values ) ? $allowed_values[0] : $allowed_values;
		}
		return $show_if;
	}
}

new Switcher_Module();
